export default function Poem() {
  let output = [];

  // Remplir le tableau résultat
  poem.lines.forEach((line, i) => {
    output.push(
      <hr key={i + '-separator'} />
    );
    output.push(
      <p key={i + '-text'}>
        {line}
      </p>
    );
  });
  // Retirer le premier <hr />
  output.shift();

  return (
    <article>
      {output}
    </article>
  );
}

